@pytest.mark.parametrize("name,expected", [("OutdatedCursor", "cursor_expired"), ("FutureCursor", "invalid_job"), ("new-advisory", "transport_error")])
def test_advisory_does_not_advance_cursor(name: str, expected: str) -> None:
    """上游可继续发数据，消费者仍应在提示后停止，不接受静默回到 live。"""
    def handler(ws):
        """把提示放在数据前，并等待客户端主动终止。"""
