def test_appview_missing_and_stale_cache_do_not_prove_deletion() -> None:
    """两个 URI 只返回一个：缺项 unresolved，新鲜度仍 unknown。"""
    result = observe_posts(("at://synthetic/one", "at://synthetic/two"), b'{"posts":[{"uri":"at://synthetic/one"}]}')
    assert result == {"returned": 1, "unresolved": 1, "freshness_lower_bound": "unknown", "deletion_confirmed": False}
    assert observe_posts(("at://synthetic/one",), b'{"posts":[]}')["deletion_confirmed"] is False
    for body in [b'{"posts":[{"uri":"other"}]}', b'{"posts":[{"uri":"at://synthetic/one"},{"uri":"at://synthetic/one"}]}']:
        with pytest.raises(WireDecodeError):
            observe_posts(("at://synthetic/one",), body)
    with pytest.raises(ValueError):
        observe_posts(tuple(str(i) for i in range(26)), b'{"posts":[]}')


